WITH chain AS (SELECT COALESCE(parent_id, id) AS root, min(published) AS first FROM manuscripts WHERE published IS NOT NULL GROUP BY 1) SELECT g.name AS station, m.short_id, m.submission->>'datePublished' AS date_published, to_char(c.first AT TIME ZONE 'UTC', 'YYYY-MM-DD') AS first_online, count(*) AS versions FROM manuscripts m JOIN chain c ON c.root = COALESCE(m.parent_id, m.id) JOIN groups g ON g.id = m.group_id WHERE m.submission->>'firstPublishedOn' IS NULL GROUP BY 1, 2, 3, 4 ORDER BY 1, 2;
